import numpy as np
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
def test(cols,name):
    X=np.column_stack(cols); c,_,_,_=np.linalg.lstsq(X,y,rcond=None)
    r=y-X@c; print(name, np.mean(r**2)/np.var(y), np.max(np.abs(r)))
    return c
for deg in [2,3,4]:
    cols=[]
    for p in range(4):
        for d in range(deg+1):
            cols.append(A**p*t**d)
    test(cols,f'A^0..3 poly t deg{deg}')
for deg in [2,3,4]:
    cols=[]
    for p in [0,1,2]:
        for d in range(deg+1):
            cols.append(A**p*t**d)
    test(cols,f'A^0..2 poly t deg{deg}')
for deg in [2,3,4]:
    cols=[]
    for p in [0,1,2,3,4]:
